#!/usr/bin/env node
/**
 * Hook PreToolUse — impedisce che un commit porti con sé credenziali.
 *
 * Si attiva solo sui comandi git commit. Ispeziona ciò che sta per essere
 * committato, non l'intero albero: un falso positivo su un file non in stage
 * bloccherebbe il lavoro senza motivo.
 */
import { readFileSync } from "node:fs";
import { execSync } from "node:child_process";

const input = (() => {
  try {
    return JSON.parse(readFileSync(0, "utf-8"));
  } catch {
    return null;
  }
})();

const comando = input?.tool_input?.command ?? "";
if (!/\bgit\s+commit\b/.test(comando)) process.exit(0);

let staged;
try {
  staged = execSync("git diff --cached -U0", { encoding: "utf-8", maxBuffer: 20 * 1024 * 1024 });
} catch {
  process.exit(0);
}

const schemi = [
  { nome: "chiave API Anthropic", regex: /sk-ant-[A-Za-z0-9_-]{20,}/ },
  { nome: "JWT service_role Supabase", regex: /"role"\s*:\s*"service_role"/ },
  { nome: "token GitHub", regex: /\bgh[pousr]_[A-Za-z0-9]{30,}/ },
  { nome: "chiave privata", regex: /-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----/ },
  { nome: "chiave AWS", regex: /\bAKIA[0-9A-Z]{16}\b/ },
];

// Le righe aggiunte sono le uniche che contano: quelle rimosse non entrano nel commit.
const aggiunte = staged
  .split("\n")
  .filter((r) => r.startsWith("+") && !r.startsWith("+++"))
  .join("\n");

const trovati = schemi.filter((s) => s.regex.test(aggiunte));

if (trovati.length === 0) process.exit(0);

console.error(
  `COMMIT BLOCCATO — nelle modifiche in stage c'è: ${trovati.map((t) => t.nome).join(", ")}.\n\n` +
    `Rimuovi il segreto dal codice, spostalo in un file .env (già in .gitignore),\n` +
    `poi rifai 'git add' e riprova. Se è un falso positivo, dillo all'utente\n` +
    `invece di aggirare il controllo.`,
);
process.exit(2);

#!/usr/bin/env node
/**
 * Hook PostToolUse — controllo statico di accessibilità sui file .tsx modificati.
 *
 * Cerca solo violazioni certe e verificabili con una regex: niente euristiche
 * che generano falsi positivi, perché un hook che grida al lupo viene ignorato.
 * Uscita 2 = il modello riceve l'elenco e corregge prima di proseguire.
 */
import { readFileSync } from "node:fs";

const leggiInput = () => {
  try {
    return JSON.parse(readFileSync(0, "utf-8"));
  } catch {
    return null;
  }
};

const input = leggiInput();
const percorso = input?.tool_input?.file_path ?? "";

if (!percorso.endsWith(".tsx")) process.exit(0);

let codice;
try {
  codice = readFileSync(percorso, "utf-8");
} catch {
  process.exit(0);
}

const righe = codice.split("\n");
const problemi = [];

const segnala = (indice, regola, correzione) => {
  problemi.push(`  riga ${indice + 1}: ${regola}\n    → ${correzione}`);
};

righe.forEach((riga, i) => {
  // <div onClick> e simili: invisibili a tastiera e screen reader
  if (/<(div|span|p|li)\b[^>]*\sonClick=/.test(riga)) {
    segnala(i, "elemento non interattivo con onClick", "usa <button type=\"button\"> o <a href>");
  }

  // focus soppresso senza sostituto
  if (/outline:\s*["']?none|outline-none/.test(riga) && !/focus-visible/.test(riga)) {
    segnala(i, "focus visivo rimosso", "aggiungi focus-visible:outline-2 focus-visible:outline-offset-2");
  }

  // immagini senza alt
  if (/<img\b(?![^>]*\balt=)/.test(riga)) {
    segnala(i, "<img> senza attributo alt", "aggiungi alt=\"descrizione\" oppure alt=\"\" se decorativa");
  }

  // tabindex positivo: stravolge l'ordine di tabulazione
  if (/tabIndex=\{?["']?[1-9]/.test(riga)) {
    segnala(i, "tabindex positivo", "usa solo tabIndex={0} o tabIndex={-1}");
  }

  // testo grigio su superficie chiara: 4.09:1, sotto la soglia AA
  if (/text-muted\b/.test(riga) && /bg-surface\b/.test(riga)) {
    segnala(i, "text-muted su bg-surface = 4.09:1 (serve 4.5:1)", "usa text-muted-surface (5.75:1)");
  }
});

if (problemi.length === 0) process.exit(0);

console.error(
  `Accessibilità — ${problemi.length} problem${problemi.length === 1 ? "a" : "i"} in ${percorso}:\n` +
    problemi.join("\n") +
    `\n\nCorreggili prima di proseguire. Per un'analisi completa usa l'agente revisore-accessibilita.`,
);
process.exit(2);

#!/usr/bin/env node
/**
 * Hook Stop — esegue il typecheck a fine turno.
 *
 * Non gira su ogni modifica: con tsc a 2-3 secondi per file rallenterebbe
 * troppo. Gira una volta sola, quando il modello sta per dichiarare finito,
 * che è esattamente il momento in cui un errore di tipo non deve passare.
 *
 * Uscita 2 = il turno non si chiude e il modello riceve gli errori da correggere.
 */
import { readFileSync, existsSync } from "node:fs";
import { execSync } from "node:child_process";

const input = (() => {
  try {
    return JSON.parse(readFileSync(0, "utf-8"));
  } catch {
    return null;
  }
})();

// Il turno è già stato ripreso una volta da questo hook: non insistere,
// altrimenti un errore che il modello non sa correggere diventa un ciclo.
if (input?.stop_hook_active) process.exit(0);

if (!existsSync("app/node_modules")) process.exit(0);

try {
  execSync("npx tsc -b", { cwd: "app", encoding: "utf-8", stdio: "pipe" });
  process.exit(0);
} catch (errore) {
  const output = `${errore.stdout ?? ""}${errore.stderr ?? ""}`.trim();
  const righe = output.split("\n").filter((r) => /error TS\d+/.test(r));

  if (righe.length === 0) process.exit(0);

  console.error(
    `Il typecheck non passa — ${righe.length} error${righe.length === 1 ? "e" : "i"}:\n\n` +
      righe.slice(0, 15).join("\n") +
      (righe.length > 15 ? `\n... e altri ${righe.length - 15}` : "") +
      `\n\nCorreggili prima di chiudere.`,
  );
  process.exit(2);
}

#!/usr/bin/env node
/**
 * Calcola la frontiera dei ticket: quelli i cui bloccanti sono tutti completati
 * e che quindi possono partire subito.
 *
 *   node .claude/scripts/frontiera.mjs                  tutti i lavori in .scratch/
 *   node .claude/scripts/frontiera.mjs <cartella>       una cartella di ticket
 *   node .claude/scripts/frontiera.mjs --json           output per un altro programma
 *
 * Serve a /buildmatt: dedurre le dipendenze leggendo i ticket a occhio funziona
 * finché i ticket sono tre. Questo le calcola.
 *
 * Formato atteso (template di to-tickets):
 *   # 03: Titolo del ticket
 *   **Blocked by:** 01, 02        oppure   None (can start immediately)
 *   **Status:** ready-for-agent   oppure   done
 *   - [ ] criterio di accettazione
 */
import { readFileSync, readdirSync, existsSync, statSync } from "node:fs";
import { join } from "node:path";

const argomenti = process.argv.slice(2);
const json = argomenti.includes("--json");
const percorsoIndicato = argomenti.find((a) => !a.startsWith("--"));

/** Trova le cartelle che contengono ticket. */
function trovaCartelle() {
  if (percorsoIndicato) return [percorsoIndicato];

  const radice = ".scratch";
  if (!existsSync(radice)) return [];

  return readdirSync(radice)
    .map((nome) => join(radice, nome, "issues"))
    .filter((p) => existsSync(p) && statSync(p).isDirectory());
}

function leggiTicket(cartella) {
  return readdirSync(cartella)
    .filter((f) => f.endsWith(".md"))
    .sort()
    .map((file) => {
      const testo = readFileSync(join(cartella, file), "utf-8");

      const intestazione = testo.match(/^#\s*(\d+)\s*:\s*(.+)$/m);
      const numero = intestazione ? intestazione[1].padStart(2, "0") : file.slice(0, 2);
      const titolo = intestazione ? intestazione[2].trim() : file;

      const rigaBloccanti = testo.match(/\*\*Blocked by:\*\*\s*(.+)/i);
      const grezzo = rigaBloccanti ? rigaBloccanti[1].trim() : "";
      // "None (can start immediately)", "nessuno", "-" valgono tutti come nessun blocco
      const bloccanti = /^(none|nessuno|-|n\/a)\b/i.test(grezzo)
        ? []
        : (grezzo.match(/\d+/g) || []).map((n) => n.padStart(2, "0"));

      const rigaStato = testo.match(/\*\*Status:\*\*\s*(.+)/i);
      const stato = rigaStato ? rigaStato[1].trim().toLowerCase() : "";

      const criteri = testo.match(/^- \[( |x)\]/gim) || [];
      const spuntati = criteri.filter((c) => /x/i.test(c)).length;

      // Completato se lo stato lo dice, o se tutti i criteri sono spuntati
      const completato =
        /\b(done|completato|closed|chiuso|merged)\b/.test(stato) ||
        (criteri.length > 0 && spuntati === criteri.length);

      return { numero, titolo, bloccanti, stato, completato, criteri: criteri.length, spuntati, file };
    });
}

const cartelle = trovaCartelle();

if (cartelle.length === 0) {
  const messaggio = percorsoIndicato
    ? `Nessun ticket in ${percorsoIndicato}`
    : "Nessun ticket trovato in .scratch/*/issues/. Genera i ticket con /to-tickets.";
  if (json) console.log(JSON.stringify({ errore: messaggio, frontiera: [] }, null, 2));
  else console.error(messaggio);
  process.exit(1);
}

const risultati = [];

for (const cartella of cartelle) {
  const ticket = leggiTicket(cartella);
  const fatti = new Set(ticket.filter((t) => t.completato).map((t) => t.numero));

  const frontiera = ticket.filter((t) => !t.completato && t.bloccanti.every((b) => fatti.has(b)));
  const attesa = ticket.filter((t) => !t.completato && !t.bloccanti.every((b) => fatti.has(b)));

  // Un bloccante citato che non corrisponde a nessun ticket è un errore nel piano:
  // bloccherebbe per sempre un ticket che nessuno sbloccherà mai.
  const numeri = new Set(ticket.map((t) => t.numero));
  const fantasma = ticket.flatMap((t) =>
    t.bloccanti.filter((b) => !numeri.has(b)).map((b) => ({ ticket: t.numero, bloccante: b })),
  );

  risultati.push({ cartella, totale: ticket.length, completati: ticket.length - frontiera.length - attesa.length, frontiera, attesa, fantasma });
}

if (json) {
  console.log(JSON.stringify(risultati, null, 2));
  process.exit(0);
}

for (const r of risultati) {
  console.log(`\n${r.cartella}  —  ${r.completati}/${r.totale} completati\n`);

  if (r.fantasma.length) {
    console.log("  ATTENZIONE — bloccanti che non esistono:");
    r.fantasma.forEach((f) => console.log(`    ticket ${f.ticket} attende ${f.bloccante}, che non c'è`));
    console.log("");
  }

  if (r.frontiera.length === 0 && r.attesa.length === 0) {
    console.log("  Tutti i ticket sono completati.\n");
    continue;
  }

  console.log(`  PRONTI ORA (${r.frontiera.length}) — un subagent ciascuno:`);
  r.frontiera.forEach((t) =>
    console.log(`    ${t.numero}  ${t.titolo}${t.criteri ? `  [${t.spuntati}/${t.criteri}]` : ""}`),
  );

  if (r.attesa.length) {
    console.log(`\n  IN ATTESA (${r.attesa.length}):`);
    r.attesa.forEach((t) => console.log(`    ${t.numero}  ${t.titolo}  ← attende ${t.bloccanti.join(", ")}`));
  }
  console.log("");
}

/**
 * Genera presentazione/guida/alberatura.json — l'indice navigabile del progetto.
 *
 * La lista dei file viene da `git ls-files`: rispetta già .gitignore e su
 * OneDrive è ordini di grandezza più veloce di una scansione ricorsiva.
 *
 * Le descrizioni sono scritte a mano in descrizioni.mjs. Quelle mancanti non
 * vengono inventate: diventano un TODO visibile nella pagina e nel conteggio
 * finale, così un file nuovo o rinominato si nota subito.
 *
 * Uso: npm run alberatura
 */

import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync, statSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { FILE, descrizioneDiGruppo, descrizioneCartella } from "./descrizioni.mjs";

const RADICE = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const USCITA = join(RADICE, "presentazione", "guida", "alberatura.json");

/** Oltre questa soglia il file viene troncato: nessuno legge 3000 righe in un pannello. */
const MAX_CARATTERI = 30_000;

const ESCLUDI = /\.(woff2|png|jpe?g|ico|gif|pdf|svg)$|package-lock\.json$|^presentazione\/vendor\/|^app\/dist\//;

const elenco = execFileSync("git", ["ls-files"], { cwd: RADICE, encoding: "utf8" })
  .split("\n")
  .map((r) => r.trim())
  .filter((r) => r && !ESCLUDI.test(r))
  .sort();

const radice = { nome: "", tipo: "cartella", figli: [] };
let inclusi = 0;
let troncati = 0;
const senzaDescrizione = [];

for (const percorso of elenco) {
  const parti = percorso.split("/");
  let nodo = radice;

  // Crea le cartelle intermedie una sola volta.
  for (let i = 0; i < parti.length - 1; i++) {
    const via = parti.slice(0, i + 1).join("/");
    let figlio = nodo.figli.find((f) => f.tipo === "cartella" && f.nome === parti[i]);
    if (!figlio) {
      const desc = descrizioneCartella(via);
      if (!desc) senzaDescrizione.push(via + "/");
      figlio = { nome: parti[i], tipo: "cartella", via, desc: desc || "", manca: !desc, figli: [] };
      nodo.figli.push(figlio);
    }
    nodo = figlio;
  }

  let contenuto;
  try {
    contenuto = readFileSync(join(RADICE, percorso), "utf8");
  } catch {
    continue; // file non leggibile come testo: lo saltiamo invece di sporcare l'indice
  }

  const peso = statSync(join(RADICE, percorso)).size;
  let tagliato = false;
  if (contenuto.length > MAX_CARATTERI) {
    contenuto = contenuto.slice(0, MAX_CARATTERI);
    tagliato = true;
    troncati++;
  }

  const desc = FILE[percorso] || descrizioneDiGruppo(percorso);
  if (!desc) senzaDescrizione.push(percorso);

  nodo.figli.push({
    nome: parti.at(-1),
    tipo: "file",
    via: percorso,
    desc,
    manca: !desc,
    peso,
    righe: contenuto.split("\n").length,
    tagliato,
    contenuto,
  });
  inclusi++;
}

// Cartelle prima dei file, poi alfabetico: l'occhio cerca la struttura, non i nomi.
function ordina(nodo) {
  nodo.figli.sort((a, b) => {
    if (a.tipo !== b.tipo) return a.tipo === "cartella" ? -1 : 1;
    return a.nome.localeCompare(b.nome, "it");
  });
  nodo.figli.filter((f) => f.tipo === "cartella").forEach(ordina);
}
ordina(radice);

writeFileSync(
  USCITA,
  JSON.stringify({ generato: new Date().toISOString(), daDescrivere: senzaDescrizione, figli: radice.figli }),
  "utf8",
);

const kb = (statSync(USCITA).size / 1024).toFixed(0);
console.log(`alberatura.json — ${inclusi} file, ${kb} KB${troncati ? `, ${troncati} troncati` : ""}`);

if (senzaDescrizione.length) {
  console.log(`\n⚠ ${senzaDescrizione.length} voci senza descrizione. Aggiungile in .claude/scripts/descrizioni.mjs:`);
  for (const v of senzaDescrizione) console.log(`   ${v}`);
} else {
  console.log("Tutte le voci hanno una descrizione.");
}

/* Font del brand Accenture — estratti da accenture.com
   Graphik: testo e titoli. GT Sectra Fine: voce editoriale (serif).
   Entrambi sono proprietari: uso interno Accenture, non ridistribuire pubblicamente. */

@font-face {
  font-family: "Graphik";
  font-weight: 400;
  font-style: normal;
  font-display: swap;
  src: local("Graphik-Regular-Web"), url("./fonts/graphik-regular-web.woff2") format("woff2");
}

@font-face {
  font-family: "Graphik";
  font-weight: 500;
  font-style: normal;
  font-display: swap;
  src: local("Graphik-Medium-Web"), url("./fonts/graphik-medium-web.woff2") format("woff2");
}

@font-face {
  font-family: "Graphik";
  font-weight: 600;
  font-style: normal;
  font-display: swap;
  src: local("Graphik-Semibold-Web"), url("./fonts/graphik-semibold-web.woff2") format("woff2");
}

@font-face {
  font-family: "GT Sectra Fine";
  font-weight: 300;
  font-style: normal;
  font-display: swap;
  src: local("GT-Sectra-Fine-Book"), url("./fonts/GT-Sectra-Fine-Book.woff2") format("woff2");
}

/* ============================================================================
   ACCENTURE DESIGN SYSTEM
   Token e componenti estratti da accenture.com/it-it (settembre 2026).
   Ogni valore qui è misurato dal sito reale, non stimato.
   Dipende da: assets/fonts.css
   ============================================================================ */

@import "./assets/fonts.css";

/* --------------------------------------------------------------------------
   1. TOKEN
   -------------------------------------------------------------------------- */
:root {
  /* Colori del brand */
  --acn-purple:         #A100FF;  /* primario: riempimenti, accenti, il segno ">" */
  --acn-purple-2:       #7500C0;  /* secondario: hover, testo viola su chiaro */
  --acn-purple-3:       #460073;  /* terziario: fondi profondi */
  --acn-purple-active:  #57008F;  /* stato :active dei bottoni */
  --acn-purple-deep:    #39005E;  /* fondo card "announcement" */
  --acn-purple-light:   #BE82FF;  /* viola su fondo SCURO — 7.83:1 su nero */
  --acn-purple-focus:   #DCAFFF;  /* anello di focus su fondo scuro */

  /* Neutri */
  --acn-black:          #000000;
  --acn-white:          #FFFFFF;
  --acn-surface-dark:   #202020;  /* card video / interviste */
  --acn-surface-dark-2: #2B2B2B;  /* superfici scure sollevate */
  --acn-surface-light:  #F1F1EF;  /* grigio caldo: card chiare, sezioni */
  --acn-border-light:   #E3E3DF;  /* bordi e divisori su chiaro */
  --acn-grey:           #A2A2A0;  /* testo attenuato — solo su fondo SCURO */
  --acn-grey-on-light:  #5F5F5F;  /* testo attenuato su fondo chiaro */

  /* Tipografia */
  --acn-font:        "Graphik", Arial, Helvetica, sans-serif;
  --acn-font-serif:  "GT Sectra Fine", Palatino, "Times New Roman", serif;

  /* Spaziatura — scala reale del sito */
  --acn-space-sm:  16px;
  --acn-space-md:  32px;
  --acn-space-lg:  48px;
  --acn-space-xl:  96px;
  --acn-space-xxl: 160px;

  /* Struttura */
  --acn-header-h:   72px;
  --acn-nav-h:      56px;
  --acn-max-width:  1920px;
  --acn-gutter:     80px;   /* padding orizzontale desktop */

  /* Movimento — la firma del brand */
  --acn-ease:       cubic-bezier(0.85, 0, 0, 1);
  --acn-ease-in:    cubic-bezier(0.22, 0, 0.63, 1);
  --acn-ease-out:   cubic-bezier(0.38, 0, 0, 1);
  --acn-duration:   550ms;
  --acn-duration-l: 750ms;

  /* Angoli: il brand è squadrato. 0 ovunque. */
  --acn-radius: 0;
}

/* --------------------------------------------------------------------------
   2. BASE
   -------------------------------------------------------------------------- */
*, *::before, *::after { box-sizing: border-box; }

body {
  margin: 0;
  font-family: var(--acn-font);
  font-size: 16px;
  line-height: 1.5;
  font-weight: 400;
  background: var(--acn-black);
  color: var(--acn-white);
  -webkit-font-smoothing: antialiased;
}

/* Tema chiaro: applica .acn-light a una sezione o al body */
.acn-light {
  background: var(--acn-white);
  color: var(--acn-black);
}

/* Focus visibile — obbligatorio, mai rimuoverlo */
/* La pagina è scura per default, quindi il default è l'anello chiaro.
   L'eccezione è la sezione chiara. Non invertire questi due: un selettore tipo
   `body:not(.acn-light)` è sempre vero (la classe sta sulle sezioni, non sul body)
   e finirebbe per applicare l'anello chiaro anche dentro le sezioni chiare,
   dove #DCAFFF su #F1F1EF dà 1.6:1 — invisibile. */
:focus-visible {
  outline: 2px solid var(--acn-purple-focus); /* 11.62:1 su nero */
  outline-offset: 8px;
}
.acn-light :focus-visible {
  outline-color: var(--acn-purple);           /* 4.69:1 su #F1F1EF */
}

/* Salto al contenuto: primo elemento del body, visibile solo da tastiera.
   Va messo in ogni pagina, altrimenti chi naviga a tastiera deve attraversare
   tutta la navigazione a ogni schermata. */
.acn-skip-link {
  position: absolute;
  top: -100%;
  left: var(--acn-space-sm);
  z-index: 9999;
  padding: 12px 20px;
  background: var(--acn-white);
  color: var(--acn-black);
  font-weight: 500;
  text-decoration: none;
}
.acn-skip-link:focus { top: 8px; }

/* --------------------------------------------------------------------------
   3. TIPOGRAFIA
   Scala fluida: i valori sono quelli a 1440px; sopra i 1440px il sito
   scala tutto linearmente fino a 1920px (fattore 1.333).
   -------------------------------------------------------------------------- */
.acn-display {            /* titolo hero: 100px a 1440px */
  font-family: var(--acn-font);
  font-size: clamp(42px, 7vw, 100px);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: clamp(-3px, -0.03em, -1.44px);
  text-transform: uppercase;
  text-wrap: balance;
  margin: 0;
}

.acn-h1 {
  font-size: clamp(40px, 5vw, 64px);
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin: 0;
}

.acn-h2 {
  font-size: clamp(32px, 3.5vw, 48px);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: -0.03em;
  margin: 0;
}

.acn-h3 {
  font-size: clamp(24px, 2.5vw, 32px);
  font-weight: 500;
  line-height: 1.25;
  letter-spacing: -0.02em;
  margin: 0;
}

/* Voce editoriale: il serif. Usalo per citazioni e sottotitoli d'apertura,
   mai per il testo di lettura lungo. */
.acn-editorial {
  font-family: var(--acn-font-serif);
  font-size: clamp(24px, 2.5vw, 32px);
  font-weight: 300;
  line-height: 1.25;
  margin: 0;
}

.acn-body   { font-size: 16px; line-height: 1.6; font-weight: 400; }
.acn-body-l { font-size: 18px; line-height: 1.6; font-weight: 400; }

/* Etichetta sopra il titolo: maiuscolo, piccolo, spaziato */
.acn-eyebrow {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  margin: 0;
}

.acn-caption { font-size: 14px; line-height: 1.5; color: var(--acn-grey); }
.acn-light .acn-caption { color: var(--acn-grey-on-light); }

/* --------------------------------------------------------------------------
   4. LAYOUT
   -------------------------------------------------------------------------- */
.acn-container {
  width: 100%;
  max-width: var(--acn-max-width);
  margin-inline: auto;
  padding-inline: var(--acn-space-sm);
}
@media (min-width: 600px)  { .acn-container { padding-inline: var(--acn-space-lg); } }
@media (min-width: 1024px) { .acn-container { padding-inline: var(--acn-gutter); } }

.acn-section { padding-block: var(--acn-space-xl); }
@media (min-width: 1024px) { .acn-section { padding-block: var(--acn-space-xxl); } }

/* Griglia 4 / 8 / 12 colonne, come il sito */
.acn-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  column-gap: var(--acn-space-sm);
  row-gap: var(--acn-space-sm);
}
@media (min-width: 600px)  { .acn-grid { grid-template-columns: repeat(8, 1fr);  column-gap: 24px; row-gap: var(--acn-space-md); } }
@media (min-width: 1024px) { .acn-grid { grid-template-columns: repeat(12, 1fr); column-gap: var(--acn-space-md); } }
@media (min-width: 1440px) { .acn-grid { column-gap: 40px; } }

/* --------------------------------------------------------------------------
   5. BOTTONI
   Il bottone primario NON cambia colore di sfondo: un gradiente scorre da
   destra a sinistra sotto il testo. E' la firma di interazione del brand.
   -------------------------------------------------------------------------- */
.acn-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 48px;
  padding-inline: 20px;
  border: 0;
  border-radius: var(--acn-radius);
  font-family: var(--acn-font);
  font-size: 16px;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: -0.005em;
  text-decoration: none;
  cursor: pointer;
  width: fit-content;
}

/* Primario — wipe a gradiente */
.acn-btn--primary {
  position: relative;
  color: var(--acn-white);
  background-color: var(--acn-purple);
  overflow: hidden;
}
.acn-btn--primary::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image: linear-gradient(90deg, var(--acn-purple-2) 50%, var(--acn-purple) 0);
  background-size: 200% 200%;
  background-position-x: 100%;
  transition: background-position-x var(--acn-duration) var(--acn-ease);
}
.acn-btn--primary:hover::before { background-position-x: 0; }
.acn-btn--primary:active        { background-color: var(--acn-purple-active); }
.acn-btn--primary > *           { position: relative; z-index: 1; }

/* Secondario — contorno, il testo sbiadisce in hover */
.acn-btn--secondary {
  border: 1px solid currentColor;
  background: transparent;
  color: inherit;
  transition: color var(--acn-duration) var(--acn-ease),
              border-color var(--acn-duration) var(--acn-ease);
}
.acn-btn--secondary:hover  { color: var(--acn-grey); }
.acn-btn--secondary:active { color: var(--acn-border-light); border-color: var(--acn-border-light); }
.acn-light .acn-btn--secondary:hover { color: var(--acn-grey-on-light); }

/* Terziario — testo + quadrato viola con il ">". Il quadrato scivola in hover. */
.acn-btn--tertiary {
  padding: 4px 0;
  background: transparent;
  color: inherit;
  font-size: 16px;
}
.acn-btn__icon {
  position: relative;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  overflow: hidden;
  background-color: var(--acn-purple);
  color: var(--acn-white);
  transition: translate var(--acn-duration) var(--acn-ease);
}
.acn-btn__icon::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(90deg, var(--acn-purple-2) 50%, var(--acn-purple) 0);
  background-size: 200% 200%;
  background-position-x: 100%;
  transition: background-position-x var(--acn-duration) var(--acn-ease);
}
.acn-btn__icon > svg { position: relative; z-index: 1; width: 55%; height: 55%; fill: currentColor; }
.acn-btn--tertiary:hover  .acn-btn__icon         { translate: 4px; }
.acn-btn--tertiary:hover  .acn-btn__icon::before { background-position-x: 0; }
.acn-btn--tertiary:active .acn-btn__icon         { background-color: var(--acn-purple-active); }

/* --------------------------------------------------------------------------
   6. CARD
   Anatomia reale: blocco testo in alto (etichetta maiuscola + titolo),
   immagine che riempie il resto. 300x424px, nessun raggio, nessuna ombra.
   In hover l'intera card scala del 4%.
   -------------------------------------------------------------------------- */
.acn-card {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  min-height: 424px;
  overflow: hidden;
  border-radius: var(--acn-radius);
  background-color: var(--acn-black);
  color: var(--acn-white);
  text-decoration: none;
  transition: scale var(--acn-duration) var(--acn-ease);
}
.acn-card:hover,
.acn-card:focus-visible { scale: 1.04; }

.acn-card--light { background-color: var(--acn-surface-light); color: var(--acn-black); }
.acn-card--deep  { background-color: var(--acn-purple-deep);    color: var(--acn-white); }
.acn-card--dark  { background-color: var(--acn-surface-dark);   color: var(--acn-white); }

.acn-card__body    { padding: 28px 24px 24px; }
.acn-card__label   { margin: 0 0 16px; font-size: 14px; font-weight: 500; letter-spacing: 0.02em; text-transform: uppercase; }
.acn-card__title   { margin: 0; font-size: 22px; font-weight: 500; line-height: 1.25; letter-spacing: -0.02em; }
.acn-card__media   { flex: 1 1 auto; min-height: 0; overflow: hidden; }
.acn-card__media img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}

/* Griglia di card: 4 colonne a desktop */
.acn-card-grid {
  display: grid;
  gap: var(--acn-space-sm);
  grid-template-columns: 1fr;
}
@media (min-width: 600px)  { .acn-card-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; } }
@media (min-width: 1024px) { .acn-card-grid { grid-template-columns: repeat(4, 1fr); gap: var(--acn-space-md); } }

/* --------------------------------------------------------------------------
   7. HERO
   -------------------------------------------------------------------------- */
.acn-hero {
  position: relative;
  overflow: hidden;
  min-height: 400px;
  background-color: var(--acn-black);
  color: var(--acn-white);
  background-size: cover;
  background-position: center;
}
.acn-hero__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  animation: acn-fade-in 1550ms var(--acn-ease-in) var(--acn-duration) backwards;
}
.acn-hero__grid {
  position: relative;
  z-index: 1;
  display: grid;
  max-width: var(--acn-max-width);
  margin-inline: auto;
  min-height: 40vh;
  padding: 24px var(--acn-space-sm);
  grid-template-columns: repeat(4, 1fr);
  gap: var(--acn-space-sm);
}
@media (min-width: 600px)  { .acn-hero__grid { padding: var(--acn-space-lg); grid-template-columns: repeat(8, 1fr);  column-gap: 24px; row-gap: var(--acn-space-md); } }
@media (min-width: 1024px) { .acn-hero__grid { padding: 60px var(--acn-gutter); grid-template-columns: repeat(12, 1fr); column-gap: var(--acn-space-md); } }
@media (min-width: 1440px) { .acn-hero__grid { column-gap: 40px; } }

.acn-hero__headline {
  grid-column: 1 / -1;
  margin: 0;
  padding-bottom: 40px;
  font-weight: 600;
  line-height: 1.15;
  text-wrap: balance;
  text-transform: uppercase;
  font-size: clamp(42px, 11vw, 50px);
  letter-spacing: -1.44px;
  animation: acn-rise 750ms var(--acn-ease-out) var(--acn-duration) backwards;
}
@media (min-width: 600px) {
  .acn-hero__headline { line-height: 1.1; font-size: clamp(48px, 12vw, 80px); letter-spacing: -2.7px; }
}
@media (min-width: 1024px) { .acn-hero__headline { grid-column: 1 / span 8; font-size: 80px; letter-spacing: -3px; } }
@media (min-width: 1440px) { .acn-hero__headline { font-size: 100px; } }

/* Il ">" dentro la parola. Entra ruotato di 90 gradi e si raddrizza. */
.acn-hero__mark {
  display: inline-block;
  position: relative;
  bottom: 0.04em;
  height: 0.78em;
  width: 0.78em;
  fill: var(--acn-purple);
  animation: acn-mark-turn 750ms var(--acn-ease-out) 3000ms forwards;
}

.acn-hero__body {
  grid-column: 2 / -1;
  align-self: end;
  display: flex;
  flex-direction: column;
  gap: var(--acn-space-sm);
  font-size: 14px;
  line-height: 1.5;
  animation: acn-rise 1250ms var(--acn-ease-out) 1500ms backwards;
}
@media (min-width: 600px)  { .acn-hero__body { grid-column: 4 / -1; font-size: 16px; line-height: 1.6; gap: 24px; } }
@media (min-width: 1024px) { .acn-hero__body { grid-column: -5 / -1; line-height: 1.5; } }

/* Il trattino viola sopra il testo: 42x5px */
.acn-deco-line { width: 42px; height: 5px; background: var(--acn-purple); flex-shrink: 0; }

/* --------------------------------------------------------------------------
   8. LOGO
   Il logo è animato. A riposo si vede solo il ">" a tutta altezza: la parola
   "accenture" è spinta fuori dal viewBox. In hover il ">" rimpicciolisce e
   scivola a destra sopra la "t", mentre la parola risale al suo posto.
   Usa assets/logo/accenture-logo.svg con le classi qui sotto sui due path.
   -------------------------------------------------------------------------- */
.acn-logo { display: block; width: 152px; }
.acn-logo svg { display: block; width: 100%; height: auto; }

.acn-logo__mark,
.acn-logo__text {
  transition: transform var(--acn-duration) var(--acn-ease),
              translate  var(--acn-duration) var(--acn-ease),
              scale      var(--acn-duration) var(--acn-ease);
}
.acn-logo__mark { fill: var(--acn-purple); }
.acn-logo__text { fill: var(--acn-white); transform: translateY(32px); }
.acn-light .acn-logo__text { fill: var(--acn-black); }

.acn-logo:hover .acn-logo__mark,
.acn-logo:focus-visible .acn-logo__mark { scale: 0.396; translate: 88.5px; }
.acn-logo:hover .acn-logo__text,
.acn-logo:focus-visible .acn-logo__text { transform: translateY(0); }

/* Variante statica: solo il segno ">", per header compatti e favicon */
.acn-logo--mark { width: 32px; }
.acn-logo--mark .acn-logo__text { display: none; }
.acn-logo--mark .acn-logo__mark { scale: 1; translate: 0; }

/* --------------------------------------------------------------------------
   9. ANIMAZIONI
   Tutte usano la stessa curva. Il brand ha un solo modo di muoversi:
   parte veloce, frena a lungo.
   -------------------------------------------------------------------------- */
@keyframes acn-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* Il contenuto sale entrando */
@keyframes acn-rise {
  from { opacity: 0; transform: translateY(20%); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Le due metà del titolo si chiudono l'una verso l'altra */
@keyframes acn-slide-left  { from { transform: translateX(10%); }  to { transform: translateX(0); } }
@keyframes acn-slide-right { from { transform: translateX(-10%); } to { transform: translateX(0); } }

/* Il ">" si raddrizza: entra a 90 gradi, ruota a 0 */
@keyframes acn-mark-turn {
  from { transform: rotate(90deg); }
  to   { transform: rotate(0) scale(0.95) translateX(0.025em); }
}

/* Il trattino viola si apre da sinistra */
@keyframes acn-line-in {
  from { width: 0; }
  to   { width: 42px; }
}

/* Linea divisoria che si stende per tutta la larghezza */
@keyframes acn-rule-in {
  from { width: 0; }
  to   { width: 100%; }
}

/* Ingresso editoriale: sale ruotando leggermente */
@keyframes acn-editorial-in {
  from { transform: translateY(120%) rotate(6deg); }
  to   { transform: translateY(0) rotate(0); }
}

.acn-anim-rise      { animation: acn-rise 750ms var(--acn-ease-out) backwards; }
.acn-anim-fade      { animation: acn-fade-in var(--acn-duration) var(--acn-ease) backwards; }
.acn-anim-editorial { animation: acn-editorial-in var(--acn-duration-l) var(--acn-ease) backwards; }
.acn-anim-line      { animation: acn-line-in var(--acn-duration-l) var(--acn-ease) backwards; }

/* Ritardi a cascata per gli elementi in sequenza */
.acn-delay-1 { animation-delay: 100ms; }
.acn-delay-2 { animation-delay: 250ms; }
.acn-delay-3 { animation-delay: 400ms; }
.acn-delay-4 { animation-delay: 550ms; }

/* --------------------------------------------------------------------------
   10. RIVELAZIONE ALLO SCROLL
   Metti .acn-reveal sull'elemento e aggiungi .is-visible via IntersectionObserver.
   Senza JS l'elemento resta visibile: nessun contenuto sparisce mai.
   -------------------------------------------------------------------------- */
.acn-reveal {
  opacity: 1;
  transform: none;
}
.js .acn-reveal {
  opacity: 0;
  transform: translateY(24px);
  /* `scale` va ripetuto qui: senza, questa regola sovrascrive la transizione
     di hover di una card che porta anche .acn-reveal, e lo scatto diventa secco. */
  transition: opacity   var(--acn-duration-l) var(--acn-ease),
              transform var(--acn-duration-l) var(--acn-ease),
              scale     var(--acn-duration)   var(--acn-ease);
}
.js .acn-reveal.is-visible {
  opacity: 1;
  transform: none;
}

/* --------------------------------------------------------------------------
   11. MOVIMENTO RIDOTTO
   Requisito WCAG 2.3.3. Il sito vero lo rispetta: qui azzeriamo tutto e
   portiamo gli elementi al loro stato finale.
   -------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    /* Azzerare il ritardo è necessario quanto la durata: con `backwards` e un
       delay di 1500ms il corpo dell'hero resterebbe invisibile per un secondo
       e mezzo anche ad animazioni disattivate. */
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  .acn-card:hover, .acn-card:focus-visible { scale: 1; }
  .acn-btn--tertiary:hover .acn-btn__icon  { translate: 0; }
  .acn-hero__mark { transform: none; }
  .acn-deco-line  { width: 42px; }
  .js .acn-reveal { opacity: 1; transform: none; }
}

/* --------------------------------------------------------------------------
   12. UTILITY
   -------------------------------------------------------------------------- */
.acn-bg-black   { background: var(--acn-black);        color: var(--acn-white); }
.acn-bg-light   { background: var(--acn-surface-light); color: var(--acn-black); }
.acn-bg-deep    { background: var(--acn-purple-3);      color: var(--acn-white); }
.acn-text-accent      { color: var(--acn-purple-2); }     /* su fondo CHIARO */
.acn-text-accent-dark { color: var(--acn-purple-light); }  /* su fondo SCURO */
/* Rete di sicurezza: #BE82FF su #F1F1EF dà 2.37:1. Se il token per fondo scuro
   finisce dentro una sezione chiara, qui rientra automaticamente a #7500C0. */
.acn-light .acn-text-accent-dark { color: var(--acn-purple-2); }

/* Solo per lettori di schermo */
.acn-sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/**
 * Preset Tailwind con i token Accenture misurati da accenture.com.
 *
 * ATTENZIONE — questo preset è per Tailwind v3:
 *   import accenture from "../.claude/skills/accenture-brand/tailwind-preset.js";
 *   export default { presets: [accenture], content: [...] };
 *
 * Su Tailwind v4 i preset non si usano: i token si dichiarano in un blocco `@theme`
 * dentro il CSS di ingresso. Questo progetto è su v4 — l'implementazione viva è in
 * `app/src/index.css`, che è anche l'esempio migliore da copiare.
 *
 * I font vanno caricati a parte: importa assets/fonts.css nel CSS di ingresso.
 */
export default {
  theme: {
    extend: {
      colors: {
        // Viola del brand
        accent: "#A100FF",          // riempimenti, il segno ">", accenti
        "accent-2": "#7500C0",      // hover + testo viola su fondo CHIARO
        "accent-3": "#460073",      // fondi profondi
        "accent-active": "#57008F", // stato :active
        "accent-deep": "#39005E",   // fondo card scura viola
        "accent-light": "#BE82FF",  // viola su fondo SCURO — 7.83:1 su nero
        "accent-focus": "#DCAFFF",  // anello di focus su fondo scuro

        // Neutri
        ink: "#000000",
        paper: "#FFFFFF",
        surface: "#F1F1EF",         // grigio CALDO, non neutro
        "surface-dark": "#202020",
        "surface-dark-2": "#2B2B2B",
        border: "#E3E3DF",
        muted: "#A2A2A0",           // solo su fondo SCURO (8.21:1 su nero)
        "muted-on-light": "#5F5F5F", // su fondo chiaro (6.39:1 su bianco)
      },

      fontFamily: {
        sans: ['"Graphik"', "Arial", "Helvetica", "sans-serif"],
        serif: ['"GT Sectra Fine"', "Palatino", '"Times New Roman"', "serif"],
      },

      fontSize: {
        // [dimensione, { interlinea, spaziatura }]
        eyebrow: ["14px", { lineHeight: "1.2", letterSpacing: "0.02em", fontWeight: "500" }],
        body: ["16px", { lineHeight: "1.6" }],
        "body-lg": ["18px", { lineHeight: "1.6" }],
        h3: ["32px", { lineHeight: "1.25", letterSpacing: "-0.02em" }],
        h2: ["48px", { lineHeight: "1.2", letterSpacing: "-0.03em" }],
        h1: ["64px", { lineHeight: "1.15", letterSpacing: "-0.03em" }],
        display: ["100px", { lineHeight: "1.1", letterSpacing: "-3px" }],
      },

      spacing: {
        // Scala reale del sito
        sm: "16px",
        md: "32px",
        lg: "48px",
        xl: "96px",
        xxl: "160px",
        gutter: "80px",
      },

      borderRadius: {
        // Il brand è squadrato: nessun raggio.
        DEFAULT: "0",
        none: "0",
      },

      transitionTimingFunction: {
        // La curva del brand: parte veloce, frena a lungo.
        acn: "cubic-bezier(0.85, 0, 0, 1)",
        "acn-in": "cubic-bezier(0.22, 0, 0.63, 1)",
        "acn-out": "cubic-bezier(0.38, 0, 0, 1)",
      },

      transitionDuration: {
        acn: "550ms",
        "acn-lg": "750ms",
      },

      maxWidth: {
        page: "1920px",
      },

      keyframes: {
        "acn-rise": {
          from: { opacity: "0", transform: "translateY(20%)" },
          to: { opacity: "1", transform: "translateY(0)" },
        },
        "acn-fade-in": {
          from: { opacity: "0" },
          to: { opacity: "1" },
        },
        "acn-mark-turn": {
          from: { transform: "rotate(90deg)" },
          to: { transform: "rotate(0) scale(0.95) translateX(0.025em)" },
        },
        "acn-editorial-in": {
          from: { transform: "translateY(120%) rotate(6deg)" },
          to: { transform: "translateY(0) rotate(0)" },
        },
      },

      animation: {
        "acn-rise": "acn-rise 750ms cubic-bezier(0.38,0,0,1) backwards",
        "acn-fade": "acn-fade-in 550ms cubic-bezier(0.85,0,0,1) backwards",
        "acn-editorial": "acn-editorial-in 750ms cubic-bezier(0.85,0,0,1) backwards",
      },
    },
  },
};

#!/usr/bin/env node
/**
 * Calcola il rapporto di contrasto WCAG 2.2 fra due colori.
 * Uso:  node contrast.mjs "#A100FF" "#FFFFFF"
 */

function parseHex(input) {
  const h = input.trim().replace(/^#/, "");
  const full = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  if (!/^[0-9a-fA-F]{6}$/.test(full)) {
    throw new Error(`Colore non valido: "${input}" (atteso #RRGGBB o #RGB)`);
  }
  return [0, 2, 4].map((i) => parseInt(full.slice(i, i + 2), 16));
}

/** Luminanza relativa secondo WCAG 2.x */
function luminance([r, g, b]) {
  const [rs, gs, bs] = [r, g, b].map((v) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

function ratio(a, b) {
  const [l1, l2] = [luminance(parseHex(a)), luminance(parseHex(b))].sort((x, y) => y - x);
  return (l1 + 0.05) / (l2 + 0.05);
}

const [, , fg, bg] = process.argv;

if (!fg || !bg) {
  console.error('Uso: node contrast.mjs "#A100FF" "#FFFFFF"');
  process.exit(2);
}

try {
  const r = ratio(fg, bg);
  const val = Math.round(r * 100) / 100;
  const esito = (soglia) => (r >= soglia ? "PASS" : "FAIL");

  console.log(`\n  ${fg}  su  ${bg}  =  ${val}:1\n`);
  console.log(`  AA   testo normale (4.5:1)   ${esito(4.5)}`);
  console.log(`  AA   testo grande   (3.0:1)   ${esito(3)}`);
  console.log(`  AA   componenti UI  (3.0:1)   ${esito(3)}`);
  console.log(`  AAA  testo normale (7.0:1)   ${esito(7)}`);
  console.log(`  AAA  testo grande   (4.5:1)   ${esito(4.5)}\n`);

  if (r < 4.5) {
    console.log("  Nota: testo grande = almeno 24px, oppure 18.66px in grassetto.\n");
  }
  process.exit(r >= 4.5 ? 0 : 1);
} catch (err) {
  console.error(`Errore: ${err.message}`);
  process.exit(2);
}

# When to Mock

Mock at **system boundaries** only:

- External APIs (payment, email, etc.)
- Databases (sometimes - prefer test DB)
- Time/randomness
- File system (sometimes)

Don't mock:

- Your own classes/modules
- Internal collaborators
- Anything you control

## Designing for Mockability

At system boundaries, design interfaces that are easy to mock:

**1. Use dependency injection**

Pass external dependencies in rather than creating them internally:

```typescript
// Easy to mock
function processPayment(order, paymentClient) {
  return paymentClient.charge(order.total);
}

// Hard to mock
function processPayment(order) {
  const client = new StripeClient(process.env.STRIPE_KEY);
  return client.charge(order.total);
}
```

**2. Prefer SDK-style interfaces over generic fetchers**

Create specific functions for each external operation instead of one generic function with conditional logic:

```typescript
// GOOD: Each function is independently mockable
const api = {
  getUser: (id) => fetch(`/users/${id}`),
  getOrders: (userId) => fetch(`/users/${userId}/orders`),
  createOrder: (data) => fetch('/orders', { method: 'POST', body: data }),
};

// BAD: Mocking requires conditional logic inside the mock
const api = {
  fetch: (endpoint, options) => fetch(endpoint, options),
};
```

The SDK approach means:
- Each mock returns one specific shape
- No conditional logic in test setup
- Easier to see which endpoints a test exercises
- Type safety per endpoint

# Good and Bad Tests

## Good Tests

**Integration-style**: Test through real interfaces, not mocks of internal parts.

```typescript
// GOOD: Tests observable behavior
test("user can checkout with valid cart", async () => {
  const cart = createCart();
  cart.add(product);
  const result = await checkout(cart, paymentMethod);
  expect(result.status).toBe("confirmed");
});
```

Characteristics:

- Tests behavior users/callers care about
- Uses public API only
- Survives internal refactors
- Describes WHAT, not HOW
- One logical assertion per test

## Bad Tests

**Implementation-detail tests**: Coupled to internal structure.

```typescript
// BAD: Tests implementation details
test("checkout calls paymentService.process", async () => {
  const mockPayment = jest.mock(paymentService);
  await checkout(cart, payment);
  expect(mockPayment.process).toHaveBeenCalledWith(cart.total);
});
```

Red flags:

- Mocking internal collaborators
- Testing private methods
- Asserting on call counts/order
- Test breaks when refactoring without behavior change
- Test name describes HOW not WHAT
- Verifying through external means instead of interface

```typescript
// BAD: Bypasses interface to verify
test("createUser saves to database", async () => {
  await createUser({ name: "Alice" });
  const row = await db.query("SELECT * FROM users WHERE name = ?", ["Alice"]);
  expect(row).toBeDefined();
});

// GOOD: Verifies through interface
test("createUser makes user retrievable", async () => {
  const user = await createUser({ name: "Alice" });
  const retrieved = await getUser(user.id);
  expect(retrieved.name).toBe("Alice");
});
```

**Tautological tests**: Expected value restates the implementation, so the test passes by construction.

```typescript
// BAD: Expected value is recomputed the way the code computes it
test("calculateTotal sums line items", () => {
  const items = [{ price: 10 }, { price: 5 }];
  const expected = items.reduce((sum, i) => sum + i.price, 0);
  expect(calculateTotal(items)).toBe(expected);
});

// GOOD: Expected value is an independent, known literal
test("calculateTotal sums line items", () => {
  expect(calculateTotal([{ price: 10 }, { price: 5 }])).toBe(15);
});
```

