import { chiedi } from "../client.ts";

const SISTEMA = `Riscrivi testi in italiano semplice per persone che partono da zero:
adulti poco confidenti con la tecnologia o con i soldi, a volte non madrelingua.

Regole:
- Frasi sotto le 20 parole. Una frase, un'idea.
- Voce attiva, presente indicativo, seconda persona singolare.
- Nessun termine tecnico senza spiegazione immediata.
- Ogni concetto astratto accompagnato da un esempio con numeri piccoli e realistici.
- Niente modi di dire, ironia o metafore culturalmente specifiche.
- Linguaggio inclusivo con forme naturali, mai asterischi o schwa.

Restituisci SOLO il testo riscritto, senza premesse né commenti.`;

/** Riscrive un testo in linguaggio semplice. */
export async function semplifica(testo: string): Promise<string> {
  return chiedi({
    sistema: SISTEMA,
    messaggio: `Riscrivi questo testo in italiano semplice:\n\n${testo}`,
    temperatura: 0.3,
  });
}

/** Valuta la leggibilità di un testo e restituisce i punti da correggere. */
export async function valutaLeggibilita(testo: string): Promise<string> {
  return chiedi({
    sistema:
      "Sei un revisore di leggibilità. Analizza il testo e riporta: " +
      "frase più lunga (numero di parole), termini tecnici non spiegati, " +
      "concetti astratti senza esempio. Sii telegrafico: elenco puntato, niente prosa.",
    messaggio: testo,
    temperatura: 0,
  });
}

import { chiedi } from "../client.ts";
import { semplifica } from "../agenti/semplificatore.ts";

export interface Lezione {
  titolo: string;
  concetto: string;
  esempio: string;
  domanda: string;
  risposta: string;
}

/**
 * Prompt chaining in tre passaggi: ogni passaggio riceve l'output del precedente
 * e ha un compito solo. Una singola chiamata che fa tutto produce risultati più
 * generici e più difficili da correggere quando sbagliano.
 *
 *   1. struttura  → cosa insegnare e in che ordine
 *   2. contenuto  → il testo vero e proprio
 *   3. semplifica → riscrittura in linguaggio accessibile
 */
export async function generaLezione(argomento: string): Promise<Lezione> {
  // 1. Struttura
  const struttura = await chiedi({
    sistema:
      "Progetti micro-lezioni per adulti che partono da zero. " +
      "Restituisci 4 righe, una per campo, nell'ordine: TITOLO, CONCETTO, ESEMPIO, DOMANDA. " +
      "Ogni riga inizia con l'etichetta seguita da due punti. Niente altro.",
    messaggio: `Progetta una micro-lezione su: ${argomento}`,
    temperatura: 0.7,
  });

  // 2. Contenuto disteso
  const contenuto = await chiedi({
    sistema:
      "Sviluppi micro-lezioni a partire da una struttura. " +
      "Mantieni le stesse 4 etichette (TITOLO, CONCETTO, ESEMPIO, DOMANDA) e aggiungi RISPOSTA. " +
      "CONCETTO: massimo 3 frasi. ESEMPIO: con cifre concrete in euro. " +
      "DOMANDA: verifica la comprensione. Niente altro oltre alle 5 righe.",
    messaggio: struttura,
    temperatura: 0.5,
  });

  // 3. Semplificazione linguistica
  const semplificato = await semplifica(contenuto);

  return estrai(semplificato);
}

/** Estrae i campi etichettati dalla risposta del modello. */
function estrai(testo: string): Lezione {
  const campo = (etichetta: string): string => {
    const trovato = testo
      .split("\n")
      .find((riga) => riga.trim().toUpperCase().startsWith(etichetta));
    return trovato?.slice(trovato.indexOf(":") + 1).trim() ?? "";
  };

  return {
    titolo: campo("TITOLO"),
    concetto: campo("CONCETTO"),
    esempio: campo("ESEMPIO"),
    domanda: campo("DOMANDA"),
    risposta: campo("RISPOSTA"),
  };
}

#!/usr/bin/env node
/**
 * CLI degli agenti.
 *
 *   npm run semplifica -- "testo da semplificare"
 *   npm run lezione    -- "interesse composto"
 *
 * Richiede ANTHROPIC_API_KEY. Per caricarla dal .env della radice:
 *   node --env-file=../.env --experimental-strip-types src/cli.ts lezione "budget"
 */
import { semplifica, valutaLeggibilita } from "./agenti/semplificatore.ts";
import { generaLezione } from "./catene/lezione.ts";

const [comando, ...resto] = process.argv.slice(2);
const argomento = resto.join(" ").trim();

const uso = `
Uso: node --env-file=../.env --experimental-strip-types src/cli.ts <comando> <testo>

Comandi:
  semplifica <testo>     Riscrive il testo in italiano semplice
  leggibilita <testo>    Analizza la leggibilità del testo
  lezione <argomento>    Genera una micro-lezione (catena di 3 passaggi)
`;

if (!comando) {
  console.log(uso);
  process.exit(0);
}

if (!argomento) {
  console.error(`Manca il testo per il comando "${comando}".\n${uso}`);
  process.exit(2);
}

try {
  switch (comando) {
    case "semplifica":
      console.log(await semplifica(argomento));
      break;

    case "leggibilita":
      console.log(await valutaLeggibilita(argomento));
      break;

    case "lezione": {
      const lezione = await generaLezione(argomento);
      console.log(`\n  ${lezione.titolo}\n`);
      console.log(`  ${lezione.concetto}\n`);
      console.log(`  Esempio: ${lezione.esempio}\n`);
      console.log(`  Domanda: ${lezione.domanda}`);
      console.log(`  Risposta: ${lezione.risposta}\n`);
      break;
    }

    default:
      console.error(`Comando sconosciuto: "${comando}".\n${uso}`);
      process.exit(2);
  }
} catch (errore) {
  console.error(`Errore: ${errore instanceof Error ? errore.message : errore}`);
  process.exit(1);
}

import Anthropic from "@anthropic-ai/sdk";

export const MODELLO = process.env.ANTHROPIC_MODEL ?? "claude-sonnet-5";

let client: Anthropic | null = null;

/**
 * Crea il client alla prima chiamata, non all'import: così i comandi che non
 * parlano con l'API (help, validazioni) funzionano anche senza chiave configurata.
 */
function ottieniClient(): Anthropic {
  if (client) return client;

  const chiave = process.env.ANTHROPIC_API_KEY;
  if (!chiave) {
    throw new Error(
      "ANTHROPIC_API_KEY non impostata.\n" +
        "  1. copia .env.example in .env e inserisci la chiave\n" +
        "  2. rilancia con: node --env-file=../.env --experimental-strip-types src/cli.ts <comando>",
    );
  }

  client = new Anthropic({ apiKey: chiave });
  return client;
}

/**
 * Chiamata singola a Claude che restituisce testo.
 * Gli agenti del progetto passano tutti da qui: un solo punto per log e retry.
 */
export async function chiedi(opzioni: {
  sistema: string;
  messaggio: string;
  maxToken?: number;
  temperatura?: number;
}): Promise<string> {
  const risposta = await ottieniClient().messages.create({
    model: MODELLO,
    max_tokens: opzioni.maxToken ?? 2048,
    temperature: opzioni.temperatura ?? 1,
    system: opzioni.sistema,
    messages: [{ role: "user", content: opzioni.messaggio }],
  });

  // La risposta può contenere blocchi non testuali: teniamo solo il testo.
  return risposta.content
    .filter((blocco): blocco is Anthropic.TextBlock => blocco.type === "text")
    .map((blocco) => blocco.text)
    .join("\n")
    .trim();
}

